-- view profile.exp_drift
-- Generated by db/tools/export-schema.mjs from the live database. Do not edit by hand:
-- change the database through a migration in db/migrations, then re-run the exporter.

CREATE OR REPLACE VIEW profile.exp_drift AS
SELECT i.user_id,
    i.exp AS cached_exp,
    COALESCE(l.ledger_exp, 0::bigint) AS ledger_exp
   FROM profile.info i
     LEFT JOIN ( SELECT exp_transaction.user_id,
            sum(exp_transaction.amount) AS ledger_exp
           FROM profile.exp_transaction
          GROUP BY exp_transaction.user_id) l ON l.user_id = i.user_id
  WHERE i.exp <> COALESCE(l.ledger_exp, 0::bigint);
